import glob, subprocess, sys
from pathlib import Path
SRC = '"""Smoke test of candidate open LLMs for the query frame on Kaggle T4s (fp16, no bf16).\n\n    python llm_smoke.py --data DIR --out DIR [--models a,b,c] [--n 48] [--batch 16] [--clear-cache]\n\nSame prompt and parser as query_frame.py, on N queries spread over the length range. Per model: load time,\nseconds per query, JSON parse rate, entities per query and the share copied verbatim from the query, subqueries\nper query, empty/garbled outputs (fp16 overflow shows up as empty text or repeated "!"), peak GPU memory.\nWrites smoke.json (one row per model) and smoke_samples.parquet (model, qid, query, raw) for reading by hand.\nSource is ASCII-only.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport gc\nimport glob\nimport json\nimport shutil\nimport time\nfrom pathlib import Path\n\nimport pandas as pd\nimport torch\nimport transformers\n\nfrom query_frame import generate, load, normalise, parse\n\nDEFAULT = "Qwen/Qwen3.5-9B,Qwen/Qwen3.5-4B,Qwen/Qwen3-8B,Qwen/Qwen3-14B"\n\n\ndef log(msg: str) -> None:\n    print(msg, flush=True)\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=__doc__)\n    ap.add_argument("--data", type=Path, required=True)\n    ap.add_argument("--out", type=Path, required=True)\n    ap.add_argument("--models", default=DEFAULT)\n    ap.add_argument("--n", type=int, default=48)\n    ap.add_argument("--batch", type=int, default=16)\n    ap.add_argument("--max-new", type=int, default=700)\n    ap.add_argument("--clear-cache", action="store_true", help="delete the HF hub cache after each model (Kaggle only)")\n    args = ap.parse_args()\n    args.out.mkdir(parents=True, exist_ok=True)\n    try:\n        import fla  # noqa: F401  fast Gated DeltaNet kernels for Qwen3.5 linear-attention layers\n        has_fla = True\n    except ImportError:\n        has_fla = False\n    log(f"transformers {transformers.__version__}, torch {torch.__version__}, gpus {torch.cuda.device_count()}, "\n        f"fla {has_fla}")\n\n    q = pd.read_parquet(glob.glob(f"{args.data}/**/query.parquet", recursive=True)[0])\n    q = q.assign(n=q["query"].astype(str).str.len()).sort_values("n")\n    q = q.iloc[[round(i * (len(q) - 1) / (args.n - 1)) for i in range(args.n)]]  # spread over lengths\n    texts, qids = q["query"].astype(str).tolist(), q["id"].tolist()\n\n    rows, samples = [], []\n    for name in args.models.split(","):\n        row = {"model": name}\n        try:\n            t0 = time.time()\n            torch.cuda.reset_peak_memory_stats() if torch.cuda.is_available() else None\n            tok, model = load(name)\n            row["load_s"] = round(time.time() - t0)\n            t0 = time.time()\n            raw = []\n            for lo in range(0, len(texts), args.batch):\n                raw += generate(tok, model, texts[lo:lo + args.batch], args.max_new)\n            row["s_per_q"] = round((time.time() - t0) / len(texts), 2)\n            frames = [parse(r) for r in raw]\n            ok = [normalise(f, t) for f, t in zip(frames, texts) if f]\n            ents = [e for f in ok for e in f["entities"]]\n            row.update({\n                "parsed": round(len(ok) / len(texts), 3),\n                "entities_per_q": round(len(ents) / max(len(ok), 1), 2),\n                "entities_in_query": round(sum(e["in_query"] for e in ents) / max(len(ents), 1), 3),\n                "aliases_per_entity": round(sum(len(e["aliases"]) for e in ents) / max(len(ents), 1), 2),\n                "subqueries_per_q": round(sum(len(f["subqueries"]) for f in ok) / max(len(ok), 1), 2),\n                "hyde_words": round(sum(len(f["hyde"].split()) for f in ok) / max(len(ok), 1)),\n                "garbled": sum(1 for r in raw if not r.strip() or r.count("!") > 20),\n                "peak_gb": round(sum(torch.cuda.max_memory_allocated(i) for i in range(torch.cuda.device_count()))\n                                 / 2**30, 1) if torch.cuda.is_available() else 0,\n            })\n            samples += [{"model": name, "qid": int(i), "query": t, "raw": r} for i, t, r in zip(qids, texts, raw)]\n            del model\n        except Exception as e:  # one failing model must not stop the comparison\n            row["error"] = f"{type(e).__name__}: {str(e)[:300]}"\n        gc.collect()\n        torch.cuda.empty_cache() if torch.cuda.is_available() else None\n        if args.clear_cache:  # Kaggle disk is small; never on a workstation\n            shutil.rmtree(Path.home() / ".cache" / "huggingface" / "hub", ignore_errors=True)\n        rows.append(row)\n        log(json.dumps(row))\n        (args.out / "smoke.json").write_text(json.dumps(rows, indent=1))\n        pd.DataFrame(samples).to_parquet(args.out / "smoke_samples.parquet", index=False)\n\n\nif __name__ == "__main__":\n    main()\n'
MODULES = {'query_frame.py': '"""Query frame with an open-weight LLM: entities + aliases, asked aspects, sub-questions, keywords, HyDE passage.\n\n    python query_frame.py --data DIR --out DIR [--model Qwen/Qwen2.5-7B-Instruct] [--batch 16] [--max-queries N]\n\nOne JSON object per query (greedy decoding). Fields:\n  entities  [{"text", "type", "aliases"}]  type in disease|symptom|drug|test|procedure|body_part|other;\n            "text" must occur in the query (flag in_query), aliases = other names (synonyms, lay/medical, EN term)\n  aspects   subset of ASPECTS\n  subqueries 1-5 short self-contained Vietnamese questions (one per asked point)\n  keywords  Vietnamese keyword query for BM25\n  hyde      ~120-word Vietnamese passage that would answer the question (for dense retrieval)\nWrites query_frame.parquet (qid, raw, ok, + fields as JSON strings) and stats.json. Prompt is English so the\nsource stays ASCII (Kaggle decodes non-ASCII kernel source badly); outputs are Vietnamese.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport glob\nimport json\nimport re\nimport time\nfrom pathlib import Path\n\nimport pandas as pd\nimport torch\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\n\nT0 = time.time()\nASPECTS = ["symptoms", "causes", "diagnosis_tests", "treatment", "medication_dosage", "prevention",\n           "diet_lifestyle", "complications_prognosis", "pregnancy_children", "other"]\nTYPES = ["disease", "symptom", "drug", "test", "procedure", "body_part", "other"]\nSYSTEM = (\n    "You analyse Vietnamese patient questions for a medical search engine over Vietnamese health articles. "\n    "Return ONLY one JSON object, no markdown, with keys:\\n"\n    \'"entities": list of {"text": exact span copied from the question, "type": one of \' + "|".join(TYPES) + \', \'\n    \'"aliases": up to 4 other names for it (Vietnamese synonyms, lay or medical names, English term)};\\n\'\n    \'"aspects": list from [\' + ", ".join(ASPECTS) + \'] that the question asks about;\\n\'\n    \'"subqueries": 1 to 5 short self-contained Vietnamese questions, one per point asked, each naming the entity;\\n\'\n    \'"keywords": Vietnamese keywords for lexical search (entities, aliases, key symptoms), space separated;\\n\'\n    \'"hyde": a factual Vietnamese passage of about 120 words, written like a health article, that answers the \'\n    "question.\\nAll text values in Vietnamese except English aliases.")\n\n\ndef log(msg: str) -> None:\n    print(f"[{time.time() - T0:7.0f}s] {msg}", flush=True)\n\n\ndef parse(raw: str) -> dict | None:\n    m = re.search(r"\\{.*\\}", raw, re.S)\n    if not m:\n        return None\n    try:\n        obj = json.loads(m.group(0))\n    except json.JSONDecodeError:\n        return None\n    return obj if isinstance(obj, dict) else None\n\n\ndef normalise(obj: dict, query: str) -> dict:\n    low = query.lower()\n    ents = []\n    for e in obj.get("entities") or []:\n        if isinstance(e, dict) and str(e.get("text", "")).strip():\n            text = str(e["text"]).strip()\n            ents.append({"text": text, "type": e.get("type") if e.get("type") in TYPES else "other",\n                         "aliases": [str(a).strip() for a in (e.get("aliases") or []) if str(a).strip()][:4],\n                         "in_query": text.lower() in low})\n    subs = []\n    for s in obj.get("subqueries") or []:\n        if isinstance(s, dict):  # small models sometimes wrap each question: {"text": "..."}\n            s = next((v for v in s.values() if isinstance(v, str)), "")\n        if str(s).strip():\n            subs.append(str(s).strip())\n    subs = subs[:5]\n    return {"entities": ents, "aspects": [a for a in (obj.get("aspects") or []) if a in ASPECTS],\n            "subqueries": subs, "keywords": str(obj.get("keywords") or "").strip(),\n            "hyde": str(obj.get("hyde") or "").strip()}\n\n\ndef load(name: str):\n    """Tokenizer + model in fp16 (T4 has no bf16); split over GPUs only when there are several."""\n    tok = AutoTokenizer.from_pretrained(name, padding_side="left")\n    gpu = torch.cuda.is_available()\n    multi = gpu and torch.cuda.device_count() > 1\n    kw = dict(dtype=torch.float16 if gpu else torch.float32, device_map="auto" if multi else None)\n    try:\n        model = AutoModelForCausalLM.from_pretrained(name, **kw)\n    except (ValueError, KeyError):  # Qwen3.5 checkpoints are image-text-to-text; the text path still works\n        from transformers import AutoModelForImageTextToText\n        model = AutoModelForImageTextToText.from_pretrained(name, **kw)\n    model.eval()\n    if gpu and not multi:\n        model.to("cuda")\n    return tok, model\n\n\ndef generate(tok, model, queries: list[str], max_new: int) -> list[str]:\n    """Greedy answers for one batch; thinking is switched off on Qwen3-family templates."""\n    msgs = [[{"role": "system", "content": SYSTEM}, {"role": "user", "content": q}] for q in queries]\n    try:\n        prompts = [tok.apply_chat_template(m, tokenize=False, add_generation_prompt=True, enable_thinking=False)\n                   for m in msgs]\n    except TypeError:\n        prompts = [tok.apply_chat_template(m, tokenize=False, add_generation_prompt=True) for m in msgs]\n    enc = tok(prompts, return_tensors="pt", padding=True).to(model.device)\n    with torch.inference_mode():\n        gen = model.generate(**enc, max_new_tokens=max_new, do_sample=False)\n    out = tok.batch_decode(gen[:, enc["input_ids"].shape[1]:], skip_special_tokens=True)\n    return [re.sub(r"<think>.*?</think>", "", t, flags=re.S).strip() for t in out]\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=__doc__)\n    ap.add_argument("--data", type=Path, required=True)\n    ap.add_argument("--out", type=Path, required=True)\n    ap.add_argument("--model", default="Qwen/Qwen2.5-7B-Instruct")\n    ap.add_argument("--batch", type=int, default=16)\n    ap.add_argument("--max-new", type=int, default=700)\n    ap.add_argument("--max-queries", type=int, default=None)\n    args = ap.parse_args()\n    args.out.mkdir(parents=True, exist_ok=True)\n\n    queries = pd.read_parquet(glob.glob(f"{args.data}/**/query.parquet", recursive=True)[0])\n    if args.max_queries:\n        queries = queries.head(args.max_queries)\n    tok, model = load(args.model)\n    log(f"loaded {args.model}")\n    texts = queries["query"].astype(str).tolist()\n    order = sorted(range(len(texts)), key=lambda i: len(texts[i]))  # similar lengths per batch\n    raw: dict[int, str] = {}\n    for lo in range(0, len(order), args.batch):\n        idx = order[lo:lo + args.batch]\n        for i, t in zip(idx, generate(tok, model, [texts[i] for i in idx], args.max_new)):\n            raw[i] = t\n        log(f"{len(raw)}/{len(texts)}")\n\n    rows = []\n    for i, (qid, q) in enumerate(zip(queries["id"], texts)):\n        obj = parse(raw[i])\n        frame = normalise(obj, q) if obj else {"entities": [], "aspects": [], "subqueries": [], "keywords": "", "hyde": ""}\n        rows.append({"qid": int(qid), "ok": obj is not None, "raw": raw[i],\n                     **{k: json.dumps(v, ensure_ascii=False) if not isinstance(v, str) else v for k, v in frame.items()}})\n    df = pd.DataFrame(rows)\n    df.to_parquet(args.out / "query_frame.parquet", index=False)\n    ents = [e for r in rows for e in json.loads(r["entities"])]\n    stats = {"queries": len(df), "parsed": int(df["ok"].sum()),\n             "entities_per_q": round(len(ents) / len(df), 2),\n             "entities_in_query": round(sum(e["in_query"] for e in ents) / max(len(ents), 1), 3),\n             "subqueries_per_q": round(sum(len(json.loads(r["subqueries"])) for r in rows) / len(df), 2),\n             "with_hyde": int(sum(bool(r["hyde"]) for r in rows)), "seconds": round(time.time() - T0)}\n    (args.out / "stats.json").write_text(json.dumps(stats, indent=1))\n    log(json.dumps(stats))\n\n\nif __name__ == "__main__":\n    main()\n'}
script = Path("/kaggle/tmp/llm_smoke.py")
script.parent.mkdir(parents=True, exist_ok=True)
script.write_text(SRC, encoding="utf-8")
for mod_name, mod_src in MODULES.items():  # helper modules next to the script (importable)
    (script.parent / mod_name).write_text(mod_src, encoding="utf-8")
pip = []
if pip:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", *pip], check=True)
args = [a.replace("{input}", "/kaggle/input").replace("{working}", "/kaggle/working") for a in ['--data', '{input}', '--out', '{working}', '--models', 'Qwen/Qwen3.5-9B,Qwen/Qwen3.5-4B,Qwen/Qwen3-8B,Qwen/Qwen2.5-7B-Instruct', '--n', '48', '--batch', '16', '--clear-cache']]
subprocess.run([sys.executable, str(script), *args], check=True)
